import ast,base64,hashlib,json
s=base64.b64decode('').decode('utf-8')
assert hashlib.sha256(s.encode()).hexdigest()=='b57a333cf3f6ab96ae03460f66cd1d0cb351bea9cbc4755bf5f5045427e69985'
t=ast.parse(s,filename='mac_runner.py')
compile(t,'mac_runner.py','exec')
print(json.dumps({'file':'mac_runner.py','bytes':len(s.encode()),'sha256':hashlib.sha256(s.encode()).hexdigest(),'ast_and_compile_only':True,'module_executed':False,'host_calls':0,'syntax':'passed'},sort_keys=True))
